# ---------------------------------------------------------------------------
# Exception Chaining
# ---------------------------------------------------------------------------
class TestExceptionChaining:
    """Validate implicit and explicit chaining behavior."""

    def test_implicit_chaining_context(self):
        """Exceptions raised during handling must set __context__."""
        try:
            try:
                raise ValueError("root cause")
            except ValueError:
                raise ParsingError("parse failed")
        except ParsingError as exc:
            assert exc.__context__ is not None
            assert isinstance(exc.__context__, ValueError)
            assert exc.__context__.args == ("root cause",)

    def test_explicit_chaining_cause(self):
        """Exceptions raised with 'from' must set __cause__."""
        root = ValueError("root cause")
        with pytest.raises(ConvergenceError) as exc_info:
            raise ConvergenceError("solver failed") from root
        assert exc_info.value.__cause__ is root
        assert exc_info.value.__suppress_context__ is True

    def test_chained_traceback_preserved(self):
        """Full traceback must be accessible via __traceback__."""
        try:
            raise VerificationError("residual check failed")
        except VerificationError as exc:
            assert exc.__traceback__ is not None
            assert exc.__traceback__.tb_frame.f_code.co_name == "test_chained_traceback_preserved"


