class TestSerialization:
    """Validate pickle round-trip for distributed error propagation."""

    @pytest.mark.parametrize("cls", [
        MathSolverError,
        ParsingError,
        ConvergenceError,
        VerificationError,
    ])
    @pytest.mark.parametrize("message", [
        "",
        "standard message",
        "Unicode: \u03c0 \u2248 3.14159",
    ])
    def test_pickle_roundtrip(self, cls, message):
        """Exceptions must survive pickle serialization."""
        original = cls(message)
        restored = pickle.loads(pickle.dumps(original))
        assert type(restored) is cls
        assert restored.args == original.args
        assert str(restored) == message


