class TestCustomPayloads:
    """Validate dynamic attribute assignment for error context."""

    @pytest.mark.parametrize("cls", [
        ParsingError,
        ConvergenceError,
        VerificationError,
    ])
    def test_custom_attributes(self, cls):
        """Exceptions must support dynamic attribute assignment."""
        exc = cls("error")
        exc.error_code = 42
        exc.details = {"line": 10, "column": 5}
        assert exc.error_code == 42
        assert exc.details == {"line": 10, "column": 5}

    def test_parsing_error_context(self):
        """ParsingError should carry expression context."""
        exc = ParsingError("Invalid token")
        exc.expression = "2 +* 3"
        exc.position = 4
        assert exc.expression == "2 +* 3"
        assert exc.position == 4

    def test_convergence_error_metrics(self):
        """ConvergenceError should carry solver metrics."""
        exc = ConvergenceError("Failed to converge")
        exc.iterations = 100
        exc.residual = 1e-3
        assert exc.iterations == 100
        assert exc.residual == 1e-3


