# Catch & Raise Semantics
# ---------------------------------------------------------------------------
class TestCatchSemantics:
    """Validate catch-all behavior and specificity."""

    def test_catch_base_captures_all(self):
        """Catching MathSolverError must capture all domain exceptions."""
        for cls in [ParsingError, ConvergenceError, VerificationError]:
            with pytest.raises(MathSolverError):
                raise cls("domain error")

    def test_catch_leaf_does_not_capture_others(self):
        """Catching a leaf exception must not capture sibling exceptions."""
        with pytest.raises(ParsingError):
            raise ParsingError("parse error")
        with pytest.raises(ConvergenceError):
            raise ConvergenceError("convergence error")
        with pytest.raises(VerificationError):
            raise VerificationError("verification error")

    def test_base_exception_raised_directly(self):
        """Base exception must be raiseable directly."""
        with pytest.raises(MathSolverError):
            raise MathSolverError("base error")

    def test_exception_grouping(self):
        """Exceptions must work with except* (Python 3.11+)."""
        errors = [ParsingError("p"), ConvergenceError("c")]
        try:
            raise ExceptionGroup("multiple errors", errors)
        except* ParsingError as eg:
            assert len(eg.exceptions) == 1
            assert isinstance(eg.exceptions[0], ParsingError)
        except* ConvergenceError as eg:
            assert len(eg.exceptions) == 1
            assert isinstance(eg.exceptions[0], ConvergenceError)


